"""Manuel SDR (V8), FABRIQUÉ par tests/make_manual_sdr.py depuis docs/src/sdr_*.html : ne pas modifier à la main."""
HTML = {'fr': '<!doctype html>\n<html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Manuel SDR</title><style>\n:root {\n  --bg: #f7f7f5; --panel: #ffffff; --text: #1d2125; --muted: #5d6670; --line: #dde1e5;\n  --accent: #1f6feb; --ok: #1a7f37; --warn: #b26b00; --bad: #c62828; --code: #eef1f4;\n}\n@media (prefers-color-scheme: dark) {\n  :root:not([data-theme="light"]) {\n    --bg: #14171b; --panel: #1b1f24; --text: #e6e8eb; --muted: #9aa4ae; --line: #2c333b;\n    --accent: #58a6ff; --ok: #3fb950; --warn: #d29922; --bad: #f85149; --code: #232a31;\n  }\n}\n:root[data-theme="dark"] {\n  --bg: #14171b; --panel: #1b1f24; --text: #e6e8eb; --muted: #9aa4ae; --line: #2c333b;\n  --accent: #58a6ff; --ok: #3fb950; --warn: #d29922; --bad: #f85149; --code: #232a31;\n}\n* { box-sizing: border-box; }\nbody { margin: 0; background: var(--bg); color: var(--text);\n  font: 16px/1.6 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif; }\n.wrap { display: grid; grid-template-columns: 270px minmax(0, 1fr); gap: 32px; max-width: 1180px;\n  margin: 0 auto; padding: 24px 16px 80px; }\nnav { position: sticky; top: 16px; align-self: start; max-height: calc(100vh - 32px); overflow: auto;\n  font-size: 14px; border-right: 1px solid var(--line); padding-right: 16px; }\nnav b { display: block; margin: 0 0 8px; font-size: 13px; text-transform: uppercase; letter-spacing: .06em;\n  color: var(--muted); }\nnav a { display: block; padding: 3px 0; color: var(--text); text-decoration: none; }\nnav a:hover { color: var(--accent); }\nmain { min-width: 0; }\nh1 { font-size: 2rem; margin: 0 0 4px; }\n.sub { color: var(--muted); margin: 0 0 24px; }\nh2 { font-size: 1.4rem; margin: 48px 0 12px; padding-top: 8px; border-top: 1px solid var(--line); }\nh3 { font-size: 1.08rem; margin: 24px 0 8px; }\np, li { max-width: 74ch; }\na { color: var(--accent); }\ncode, kbd { font-family: ui-monospace, Consolas, monospace; font-size: .9em; background: var(--code);\n  border-radius: 4px; padding: 1px 5px; }\nkbd { border: 1px solid var(--line); border-bottom-width: 2px; }\ntable { border-collapse: collapse; width: 100%; max-width: 820px; margin: 12px 0; font-size: 15px; }\nth, td { border: 1px solid var(--line); padding: 6px 10px; text-align: left; vertical-align: top; }\nth { background: var(--panel); }\n.box { background: var(--panel); border: 1px solid var(--line); border-left: 4px solid var(--accent);\n  border-radius: 6px; padding: 10px 14px; margin: 14px 0; max-width: 820px; }\n.box.warn { border-left-color: var(--warn); }\n.box.ok { border-left-color: var(--ok); }\n.steps { counter-reset: s; list-style: none; padding-left: 0; }\n.steps > li { counter-increment: s; position: relative; padding-left: 38px; margin: 10px 0; }\n.steps > li::before { content: counter(s); position: absolute; left: 0; top: 1px; width: 26px; height: 26px;\n  border-radius: 50%; background: var(--accent); color: #fff; font-weight: 700; font-size: 14px;\n  display: grid; place-items: center; }\n.ok { color: var(--ok); font-weight: 600; } .warn { color: var(--warn); font-weight: 600; }\n.bad { color: var(--bad); font-weight: 600; }\n.theme { position: fixed; top: 10px; right: 12px; background: var(--panel); color: var(--text);\n  border: 1px solid var(--line); border-radius: 6px; padding: 4px 10px; cursor: pointer; font-size: 13px; }\ncode { overflow-wrap: anywhere; }\n@media (max-width: 860px) {\n  .wrap { grid-template-columns: 1fr; }\n  table { display: block; overflow-x: auto; }\n  nav { position: static; max-height: none; border-right: 0; border-bottom: 1px solid var(--line);\n    padding: 0 0 12px; columns: 2; }\n}\n@media print { .theme { display: none; } .wrap { display: block; padding: 0; } body { background: #fff; } nav { position: static; max-height: none; border: 0; columns: 2; padding: 0 0 12px; font-size: 12px; } h2, h3 { break-after: avoid; } table, .box, li { break-inside: avoid; } }\n/*pro*/\nbody { font: 16px/1.65 "Segoe UI", system-ui, -apple-system, Roboto, sans-serif; }\n.cover { display: flex; gap: 22px; align-items: center; max-width: 1148px; margin: 0 auto; padding: 34px 0 22px;\n  border-bottom: 3px solid var(--accent); }\n@media (max-width: 1180px) { .cover { margin: 0 16px; } }\n.cover img { width: 80px; height: 80px; flex: none; }\n.cover .kicker { text-transform: uppercase; letter-spacing: .14em; font-size: 12px; font-weight: 600; color: var(--muted); }\n.cover h1 { font-size: 2.5rem; line-height: 1.1; margin: 4px 0 6px; letter-spacing: -.01em; }\n.cover .sub { margin: 0; }\n.part { margin: 76px 0 0; padding: 0 0 8px; border-bottom: 2px solid var(--accent); background: none; color: var(--accent);\n  font-size: 13px; font-weight: 700; text-transform: uppercase; letter-spacing: .14em; border-radius: 0; }\nh2 { font-size: 1.5rem; font-weight: 650; margin: 46px 0 12px; border-top: 0; padding-top: 0; }\nh2 .n { color: var(--accent); margin-right: .35em; font-variant-numeric: tabular-nums; }\nh3 { font-weight: 650; }\n.box { border-radius: 4px; }\n.box.ok, .box.warn, .box.bad { color: var(--text); font-weight: 400; }   /* seule la bordure est colorée */\nfigure.shot { margin: 18px 0 22px; max-width: 900px; }\nfigure.shot img { display: block; width: 100%; height: auto; border: 1px solid var(--line); border-radius: 6px;\n  box-shadow: 0 2px 12px rgba(0, 0, 0, .14); }\nfigure.shot figcaption { font-size: 13px; color: var(--muted); margin-top: 6px; }\nnav .np { margin: 14px 0 2px; font-size: 12px; font-weight: 700; text-transform: uppercase; letter-spacing: .08em;\n  color: var(--accent); }\n@media print { .cover { margin: 0 0 18px; } .part { break-before: page; margin-top: 0; } figure.shot { break-inside: avoid; } h2 { break-after: avoid; } }\n/*/pro*/\n</style></head><body><main><header><h1>Manuel SDR</h1><p class="muted">TinySA Monitor — le poste SDR (V8)</p></header><nav><h2>Sommaire</h2><ol><li><a href="#poste">Le poste SDR</a></li>\n<li><a href="#branchement">Premier branchement</a></li>\n<li><a href="#ecoute">Écouter</a></li>\n<li><a href="#favoris">Favoris et patrouille</a></li>\n<li><a href="#surveiller">Surveiller avec le SDR</a></li>\n<li><a href="#plusieurs">Plusieurs SDR et la carte</a></li>\n<li><a href="#caler">Caler les niveaux sur le tinySA</a></li>\n<li><a href="#remonter">Remonter le temps</a></li>\n<li><a href="#demo">Le SDR démo</a></li>\n<li><a href="#emettre">Émettre avec un HackRF</a></li>\n<li><a href="#sons">Sons, générateur et alarmes</a></li>\n<li><a href="#avance">Outils avancés</a></li>\n<li><a href="#savoir">Bon à savoir</a></li></ol></nav><section id="poste"><h2>1. Le poste SDR</h2>\n<p>Un <b>SDR</b> (radio logicielle : HackRF, SDRplay RSP1B, RTL-SDR, Airspy, WiNRADiO…) reçoit une <b>fenêtre</b> de\nquelques MHz d\'un seul coup, sans trou, et peut <b>démoduler</b> : tu entends ce qui passe sur une fréquence. Le tinySA,\nlui, balaye toute une bande mais n\'écoute rien. Les deux se complètent.</p>\n<h3>Trois modes</h3>\n<p>Le bouton de mode, dans la barre du haut, choisit ce que tu utilises :</p>\n<table>\n  <tr><th>Mode</th><th>À l\'écran</th></tr>\n  <tr><td><b>📟 tinySA</b></td><td>L\'appli comme avant : spectre, waterfall, mur, liste.</td></tr>\n  <tr><td><b>📡 SDR</b></td><td>Les panneaux du poste SDR : Récepteur, Spectre, Waterfall, Mes micros.</td></tr>\n  <tr><td><b>📟+📡 Combiné</b></td><td>Le spectre du tinySA ET celui du SDR côte à côte : le tinySA surveille tout le\n    site, le SDR écoute et regarde de près.</td></tr>\n</table>\n<p>Chaque mode a une disposition de base et des <b>pré-affichages</b> (écouter, surveiller, analyser, double écran).\nEnsuite tu bouges les panneaux comme tu veux : ta disposition est retenue, et elle suit ton profil utilisateur.</p>\n<h3>Les quatre panneaux</h3>\n<ul>\n  <li><b>Récepteur</b> : ▶ / ■, le son, la grande fréquence <b>A</b> (molette sur un chiffre pour le changer), le\n    vu-mètre en dBm avec un mot (très faible, faible, bon, fort, trop fort), les favoris ⭐, la patrouille, les\n    alarmes, l\'info « c\'est quoi » et le pilote.</li>\n  <li><b>Spectre</b> : la fenêtre du SDR. Tes micros y sont marqués par leur nom. <b>Clic = écouter (A)</b>,\n    <b>clic droit = B</b>. Micro précédent / suivant, zoom, pics gardés.</li>\n  <li><b>Waterfall</b> : l\'historique de la fenêtre, A et B en traits.</li>\n  <li><b>Mes micros</b> : les micros de ce SDR avec leur niveau ; double-clic = écouter, clic droit = menu.</li>\n</ul>\n<h3>Simple, Plus, Expert</h3>\n<p>Le niveau d\'affichage de l\'appli s\'applique aussi au poste SDR. <b>Simple</b> : écouter, favoris, patrouille,\nalarmes. <b>Plus</b> : démodulation, pas, squelch, récepteur B, enregistrements. <b>Expert</b> : taille de FFT,\nréglages de l\'appareil, charge et saturation.</p>\n</section>\n<section id="branchement"><h2>2. Premier branchement</h2>\n<p>La première fois, ouvre <b>🔌 Premier branchement SDR</b> (menu du mode, ou 🔌 Matériel › 📡 SDR). L\'assistant fait\nsix étapes et dit pour chacune ✔, ⚠ ou ✖ avec quoi faire :</p>\n<ol>\n  <li><b>Mon SDR</b> : choisis le modèle exact. Il règle les débits, les gains et la plage de fréquences.</li>\n  <li><b>Le trouver</b> : l\'outil du SDR est cherché, l\'appareil détecté, un signal reçu pendant 2 s et le débit\n    vérifié. Si une ligne est ✖, elle dit pourquoi (outil manquant, pilote USB, SDR pris par un autre logiciel,\n    port USB trop lent).</li>\n  <li><b>Régler le gain tout seul</b> : chaque valeur du gain d\'entrée est essayée ; l\'appli garde <b>la plus forte qui\n    ne sature pas</b> en laissant 6 dB de marge. S\'il sature même au plus bas, elle te conseille un atténuateur.</li>\n  <li><b>Écouter un micro</b> : le poste démarre sur un de tes micros : tu dois l\'entendre.</li>\n  <li><b>Caler les niveaux</b> (facultatif) : voir le chapitre « Caler les niveaux sur le tinySA ».</li>\n  <li><b>Diagnostic</b> : un fichier résume tout (modèle, gains, résultats, messages de l\'outil). C\'est celui à\n    envoyer au support si quelque chose coince.</li>\n</ol>\n<div class="box">Les outils des SDR (hackrf_transfer, rtl_sdr, SoapySDR…) viennent du <b>kit SDR</b> à dézipper à côté\nde l\'appli, ou de PothosSDR. Le SDRplay demande aussi l\'API du fabricant, le WiNRADiO son logiciel.</div>\n</section>\n<section id="ecoute"><h2>3. Écouter</h2>\n<p>Un micro HF analogique s\'écoute comme une radio : le poste démodule la FM et te fait entendre le son. Deux façons\nrapides de se caler sur un micro :</p>\n<ul>\n  <li><b>Double-clic</b> sur son nom ou sa fréquence dans « Mes fréquences » (en mode SDR ou combiné) ;</li>\n  <li><b>clic</b> sur lui dans le spectre SDR, ou dans « Mes micros ».</li>\n</ul>\n<h3>Le réglage d\'écoute se fait tout seul</h3>\n<p>Chaque appareil a sa façon d\'émettre : FM large, désaccentuation, <b>compander</b> (le compresseur à l\'émission\net l\'expanseur à la réception). L\'appli <b>devine le bon réglage</b> d\'après ce qu\'elle sait du micro : son appareil dans\nle plan importé (EazyRF, WWB, WSM…), le nom de son groupe, son nom. La ligne 🎧 Écoute montre « auto (d\'après le\nmicro) ». Si tu changes le préréglage ou le compander, ton choix est <b>retenu pour ce micro</b> (« ✋ choisi pour ce\nmicro »), dans la liste et dans les shows.</p>\n<div class="box warn">Les systèmes <b>numériques</b> (ULX-D, Axient Digital, QLX-D, SLX-D, EW-D / EW-DX, 6000, Spectera…)\n<b>ne s\'écoutent pas</b> : leur son est codé et souvent chiffré. L\'appli le dit (📵) et continue de surveiller leur\nniveau. Les companders des marques ne sont pas publiés : ceux de l\'appli sont des approximations, réglées pour que ce\nsoit agréable à l\'oreille, pas des copies exactes.</div>\n<h3>Récepteurs A et B</h3>\n<p>En niveau Plus, un deuxième récepteur <b>B</b> écoute une autre fréquence de la même fenêtre. « A gauche / B droite »\nmet chacun dans une oreille du casque.</p>\n<h3>Squelch, volume, enregistrer</h3>\n<p>Le <b>squelch</b> coupe le souffle quand rien ne passe. <b>⏺ Son</b> enregistre ce que tu entends en WAV,\n<b>⏺ IQ</b> enregistre le signal brut de toute la fenêtre (gros fichiers, à relire dans le Temps réel). Les deux\ndemandent ton accord la première fois (on peut enregistrer des voix).</p>\n</section>\n<section id="favoris"><h2>4. Favoris et patrouille</h2>\n<h3>Favoris au pavé numérique</h3>\n<p>Mets tes micros les plus importants sur les touches <b>1 à 9 du pavé numérique</b> : clic droit sur un bouton ⭐ du\nRécepteur (« y mettre le micro écouté ») ou clic droit sur un micro dans « Mes micros ». Ensuite, <b>une touche =\nle SDR se cale sur ce micro, avec son réglage d\'écoute</b>, où que tu sois dans l\'appli.</p>\n<h3>🔁 Patrouille</h3>\n<p>La patrouille fait passer le SDR d\'un favori à l\'autre (ou de tous les micros de ce SDR), quelques secondes chacun,\npar ordre de fréquence (le SDR se recentre le moins possible).\nLes micros éteints 💤 ou en pause sont sautés. <b>Une touche du pavé, un clic sur une fréquence ou un double-clic\narrête la patrouille</b> : tu as repris la main.</p>\n</section>\n<section id="surveiller"><h2>5. Surveiller avec le SDR</h2>\n<p>La fenêtre du SDR <b>surveille aussi tes fréquences</b> : les micros qui y tombent ont leur niveau, leurs états et\nleurs alarmes, comme avec le tinySA. Si un tinySA balaye en même temps, c\'est lui qui garde la surveillance (les deux\néchelles ne sont pas mélangées).</p>\n<h3>🚨 Se caler sur les alarmes</h3>\n<p>Quand une <b>nouvelle</b> alarme arrive (conflit, intermod, absent, trop fort, pilote) sur un micro de ce SDR, le\nposte <b>s\'y cale tout seul</b> : tu entends ce qui se passe, et le journal note ce que le SDR y voit (« c\'est\nquoi »). Il ne te vole pas une fréquence que tu viens de choisir (30 s), et il reste au moins 20 s sur une alarme\navant de passer à la suivante. <b>↩ Revenir</b> te ramène où tu étais. Si le SDR est seul à surveiller et que\nl\'alarme est hors de sa fenêtre, il ne bouge pas tout seul (les autres micros perdraient leur mesure) : il te propose\n<b>🚨 Aller à l\'alarme</b>. Coche « et enregistrer le son » pour garder un\nWAV de l\'alarme (10 s d\'avant si le SDR écoutait déjà ce micro, 20 s d\'après).</p>\n<h3>🏷 C\'est quoi ?</h3>\n<p>Sous la fréquence, l\'appli dit ce qu\'elle voit sur A d\'après la forme du spectre : micro FM analogique, FM étroite\n(talkie), porteuse pure, bloc numérique, TV… avec la largeur occupée et le nombre de dB au-dessus du bruit. C\'est une\n<b>supposition</b> utile pour trier, pas une identification certaine.</p>\n<h3>🔊 Le pilote : « c\'est bien ton émetteur »</h3>\n<p>Beaucoup de micros analogiques émettent une tonalité inaudible, le <b>pilote</b>. La première fois que le SDR\nl\'entend sur un micro, il te demande <b>« c\'est bien ton émetteur ? »</b> : ✔ Oui le retient, ✖ Non l\'ignore (un\nbrouilleur peut aussi avoir un pilote). Ensuite : « ✔ c\'est bien ton émetteur ». Si une porteuse est là\n<b>sans</b> son pilote pendant 5 s, une alarme <b>PILOTE</b> se lève : c\'est peut-être un autre émetteur sur ta\nfréquence. Un pack sans pilote affiche simplement « pas de pilote vu ». Clic droit sur la ligne d\'info = oublier le\npilote (si tu as changé de pack).</p>\n</section>\n<section id="plusieurs"><h2>6. Plusieurs SDR et la carte</h2>\n<p><b>📡 Mes SDR</b> ajoute des postes (jusqu\'à 4) : chacun a son nom, son modèle, son numéro de série (pour savoir\nlequel est lequel) et <b>ses scènes</b>. Un SDR rattaché à une scène ne s\'occupe que des micros de cette scène, et\nc\'est lui qui répond au pavé numérique et aux alarmes de ces micros. Chaque poste a ses quatre panneaux, titrés à son\nnom.</p>\n<p>Sur la <b>🗺 carte du site</b>, les SDR sont des tuiles comme les tinySA : <b>glisse un SDR sur une scène</b> pour\nqu\'il la surveille ; le trait entre eux montre qui surveille quoi.</p>\n</section>\n<section id="caler"><h2>7. Caler les niveaux sur le tinySA</h2>\n<p>Un SDR mesure en <b>dBFS</b> (par rapport à son convertisseur), pas en dBm. Sans calibration, ses niveaux sont\napproximatifs. <b>📏 Caler les niveaux du SDR sur le tinySA</b> les rend comparables :</p>\n<ol>\n  <li>Mets le tinySA et le SDR en marche en même temps (mode combiné), les antennes <b>au même endroit</b>.</li>\n  <li>Allume des micros dans la fenêtre du SDR (il faut au moins 2 signaux vus par les deux).</li>\n  <li>▶ Mesurer : pendant 15 s, l\'appli compare la puissance de chaque signal (sur ± 100 kHz) vue par les deux.</li>\n  <li>Elle affiche la correction (et l\'écart entre signaux). <b>✔ Appliquer</b> la garde pour ce modèle de SDR.</li>\n</ol>\n<p>Ensuite, seuils, alarmes et niveaux du SDR sont en vrais dBm, cohérents avec le tinySA. Refais-le si tu changes\nd\'antenne, de câble ou de gain.</p>\n</section>\n<section id="remonter"><h2>8. Remonter le temps</h2>\n<p>Le poste SDR garde en mémoire les <b>dernières minutes</b> (1, 3 ou 5, ou désactivé) : le spectre et le son entendu.\n<b>⏪ Remonter le temps</b> (bouton du Récepteur) montre le waterfall de ces minutes, le plus récent en haut, avec les\nalarmes en repères.</p>\n<ul>\n  <li><b>Clic</b> sur le waterfall = choisir un instant ; la fenêtre dit sur quel micro était A à ce moment-là.</li>\n  <li><b>▶ Réécouter à partir d\'ici</b> : jusqu\'à 60 s de ce que tu entendais.</li>\n  <li><b>💾 Garder ce passage</b> : le son (WAV) et l\'image, dans le dossier des enregistrements.</li>\n</ul>\n<div class="box">Tout reste <b>en mémoire</b> et disparaît quand tu fermes l\'appli, sauf ce que tu gardes. Le son\nprend environ 11 Mo par minute et par poste.</div>\n</section>\n<section id="demo"><h2>9. Le SDR démo</h2>\n<p>Pas encore de SDR ? <b>🧪 SDR démo</b> (menu du mode) fait tourner tout le poste <b>sans matériel</b> : l\'appli\nfabrique les signaux de <b>tes micros</b>, chacun avec un son (voix « un, deux », mélodie, bips…) et un pilote. Pour que\nce soit vivant : un brouilleur passe sur ta première fréquence « doit rester libre », un micro s\'éteint de temps en\ntemps, un autre perd son pilote, et deux canaux TV sont là. Tu peux tout essayer : écoute, favoris, patrouille,\nalarmes, remonter le temps, plusieurs SDR.</p>\n<p>Clic droit sur un micro dans « Mes micros » › <b>🎵 Son de ce micro dans le SDR démo</b> pour lui donner le son de\nton choix (voir « Sons, générateur et alarmes »).</p>\n</section>\n<section id="emettre"><h2>10. Émettre avec un HackRF</h2>\n<div class="box warn"><b>Émettre à l\'antenne sans autorisation est interdit.</b> Cette fonction est faite pour\ntravailler <b>en câble</b>, avec un atténuateur de 30 dB ou plus avant l\'entrée du récepteur ou du tinySA.</div>\n<p>Un HackRF peut <b>émettre</b> (les SDRplay, RTL-SDR, Airspy et WiNRADiO ne font que recevoir).\n<b>📡 Émettre avec un HackRF</b> envoie jusqu\'à 8 signaux à la fois dans une fenêtre de quelques MHz :</p>\n<ul>\n  <li><b>micro FM</b> avec son et pilote (tester un récepteur, son squelch, l\'écoute de l\'appli) ;</li>\n  <li><b>talkie</b> (FM étroite), <b>porteuse pure</b>, <b>bloc large</b> (numérique, TV) ;</li>\n  <li><b>intermittent</b> : allumé 1 s toutes les 4 s, comme un brouilleur qui va et vient (s\'entraîner à la chasse,\n    tester les alarmes) ;</li>\n  <li>plusieurs porteuses à la fois : de l\'<b>intermodulation</b> volontaire, à observer au tinySA.</li>\n</ul>\n<p>Le gain d\'émission part de 0 dB et l\'ampli est coupé : en câble, c\'est déjà bien assez. L\'émission s\'arrête toute\nseule (1 à 30 min), à la fermeture de la fenêtre et de l\'appli, et elle est notée au journal. La case « en câble » est\nobligatoire. Un HackRF reçoit OU émet : arrête le poste SDR qui l\'utilise avant d\'émettre.</p>\n<p>Avec le <b>SDR démo</b> allumé, l\'émission est <b>simulée</b> : rien ne sort, et le SDR démo « reçoit » ce que tu\némets. Pratique pour tout essayer sans matériel.</p>\n</section>\n<section id="sons"><h2>11. Sons, générateur et alarmes</h2>\n<p>Partout où l\'appli joue ou fabrique un son, tu peux choisir la <b>source</b> :</p>\n<table>\n  <tr><th>Source</th><th>Ce que c\'est</th></tr>\n  <tr><td>Générateur : une fréquence</td><td>Une tonalité de 20 Hz à 20 kHz.</td></tr>\n  <tr><td>Générateur : balayage</td><td>De f1 à f2 en N secondes, logarithmique (autant de temps par octave) ou\n    linéaire, en boucle.</td></tr>\n  <tr><td>Bruit blanc, bruit rose</td><td>Pour écouter le comportement d\'une chaîne audio.</td></tr>\n  <tr><td>Voix, mélodie, bips, silence</td><td>Les sons de démo (silence = porteuse seule).</td></tr>\n  <tr><td>Un son de l\'appli</td><td>Alarmes critique, normale, info, appel des micros.</td></tr>\n  <tr><td>Mon fichier WAV</td><td>Ta voix, ta musique, un signal de test : joué en boucle.</td></tr>\n</table>\n<p>On la choisit : pour chaque signal émis, pour chaque micro du SDR démo, dans le <b>🎵 Générateur audio</b> (qui joue\nsur la sortie audio de l\'appli, en continu) et pour les <b>sons des alarmes</b> : ⚙ Réglages › Son › Sons des\nalarmes, un choix par son (▶ pour écouter, ↺ pour revenir au son d\'origine). Un son d\'alarme personnalisé est coupé à\n4 s ; s\'il ne peut pas être joué, l\'appli joue le son d\'origine.</p>\n<div class="box">Dans l\'écoute d\'un micro HF, les aigus au-delà de ~15 kHz sont coupés : c\'est la bande audio d\'un\nmicro, pas un défaut.</div>\n</section>\n<section id="avance"><h2>12. Outils avancés</h2>\n<ul>\n  <li><b>📡 Moniteur multicanal</b> : tous les micros d\'une fenêtre mesurés en même temps (niveau, voisins, largeur), les\n    plus importants démodulés (son, déviation, dérive, coupures), dossiers d\'incident automatiques (IQ d\'avant et\n    d\'après, rapport), phases du show (répétition / spectacle) comparées.</li>\n  <li><b>⏱ Temps réel</b> : une fenêtre fixe vue sans trou, avec persistance, signaux brefs notés, enregistrement et\n    relecture IQ.</li>\n  <li><b>📦 Rejouer un incident</b> : le rapport et l\'IQ d\'un incident, la chronologie du micro suivie à la lecture.</li>\n  <li><b>📶 Récepteurs en réseau</b> : niveaux RF, piles et alertes lus directement dans les récepteurs Shure\n    (ULX-D, QLX-D, Axient Digital…) et Sennheiser (evolution G3 / G4, EW-DX, 6000 par Sound Control), comparés à ce\n    que mesurent le tinySA et le SDR. Wisycom ne publie pas de protocole : pas de lecture directe.</li>\n  <li><b>📱 Écoute sur le téléphone</b> : la vue « Écoute » de la page web (cachée par défaut) fait entendre le SDR\n    sur un téléphone du réseau, avec le code PIN.</li>\n</ul>\n</section>\n<section id="savoir"><h2>13. Bon à savoir</h2>\n<ul>\n  <li>Un SDR n\'est utilisable que par <b>un logiciel à la fois</b> : ferme l\'autre logiciel (et les fenêtres SDR de\n    l\'appli qui l\'utilisent) avant de démarrer le poste.</li>\n  <li>La <b>fenêtre</b> d\'un SDR fait quelques MHz (HackRF jusqu\'à ~15 MHz, RSP1B ~8 MHz, RTL-SDR ~2 MHz) : quand A sort\n    de la fenêtre, le poste se recentre tout seul.</li>\n  <li>Un HackRF a 8 bits : un émetteur très fort à côté le sature vite. Le réglage automatique du gain et un\n    atténuateur règlent ça.</li>\n  <li>Les niveaux d\'un SDR ne sont en vrais dBm qu\'après <b>calibration</b> sur le tinySA (ou pour un WiNRADiO,\n    calibré d\'usine).</li>\n  <li>Le son et l\'IQ enregistrés sont gardés le temps que tu choisis (📡 Réglages SDR › enregistrements gardés),\n    puis effacés.</li>\n</ul>\n</section></main></body></html>\n', 'en': '<!doctype html>\n<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>SDR manual</title><style>\n:root {\n  --bg: #f7f7f5; --panel: #ffffff; --text: #1d2125; --muted: #5d6670; --line: #dde1e5;\n  --accent: #1f6feb; --ok: #1a7f37; --warn: #b26b00; --bad: #c62828; --code: #eef1f4;\n}\n@media (prefers-color-scheme: dark) {\n  :root:not([data-theme="light"]) {\n    --bg: #14171b; --panel: #1b1f24; --text: #e6e8eb; --muted: #9aa4ae; --line: #2c333b;\n    --accent: #58a6ff; --ok: #3fb950; --warn: #d29922; --bad: #f85149; --code: #232a31;\n  }\n}\n:root[data-theme="dark"] {\n  --bg: #14171b; --panel: #1b1f24; --text: #e6e8eb; --muted: #9aa4ae; --line: #2c333b;\n  --accent: #58a6ff; --ok: #3fb950; --warn: #d29922; --bad: #f85149; --code: #232a31;\n}\n* { box-sizing: border-box; }\nbody { margin: 0; background: var(--bg); color: var(--text);\n  font: 16px/1.6 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif; }\n.wrap { display: grid; grid-template-columns: 270px minmax(0, 1fr); gap: 32px; max-width: 1180px;\n  margin: 0 auto; padding: 24px 16px 80px; }\nnav { position: sticky; top: 16px; align-self: start; max-height: calc(100vh - 32px); overflow: auto;\n  font-size: 14px; border-right: 1px solid var(--line); padding-right: 16px; }\nnav b { display: block; margin: 0 0 8px; font-size: 13px; text-transform: uppercase; letter-spacing: .06em;\n  color: var(--muted); }\nnav a { display: block; padding: 3px 0; color: var(--text); text-decoration: none; }\nnav a:hover { color: var(--accent); }\nmain { min-width: 0; }\nh1 { font-size: 2rem; margin: 0 0 4px; }\n.sub { color: var(--muted); margin: 0 0 24px; }\nh2 { font-size: 1.4rem; margin: 48px 0 12px; padding-top: 8px; border-top: 1px solid var(--line); }\nh3 { font-size: 1.08rem; margin: 24px 0 8px; }\np, li { max-width: 74ch; }\na { color: var(--accent); }\ncode, kbd { font-family: ui-monospace, Consolas, monospace; font-size: .9em; background: var(--code);\n  border-radius: 4px; padding: 1px 5px; }\nkbd { border: 1px solid var(--line); border-bottom-width: 2px; }\ntable { border-collapse: collapse; width: 100%; max-width: 820px; margin: 12px 0; font-size: 15px; }\nth, td { border: 1px solid var(--line); padding: 6px 10px; text-align: left; vertical-align: top; }\nth { background: var(--panel); }\n.box { background: var(--panel); border: 1px solid var(--line); border-left: 4px solid var(--accent);\n  border-radius: 6px; padding: 10px 14px; margin: 14px 0; max-width: 820px; }\n.box.warn { border-left-color: var(--warn); }\n.box.ok { border-left-color: var(--ok); }\n.steps { counter-reset: s; list-style: none; padding-left: 0; }\n.steps > li { counter-increment: s; position: relative; padding-left: 38px; margin: 10px 0; }\n.steps > li::before { content: counter(s); position: absolute; left: 0; top: 1px; width: 26px; height: 26px;\n  border-radius: 50%; background: var(--accent); color: #fff; font-weight: 700; font-size: 14px;\n  display: grid; place-items: center; }\n.ok { color: var(--ok); font-weight: 600; } .warn { color: var(--warn); font-weight: 600; }\n.bad { color: var(--bad); font-weight: 600; }\n.theme { position: fixed; top: 10px; right: 12px; background: var(--panel); color: var(--text);\n  border: 1px solid var(--line); border-radius: 6px; padding: 4px 10px; cursor: pointer; font-size: 13px; }\ncode { overflow-wrap: anywhere; }\n@media (max-width: 860px) {\n  .wrap { grid-template-columns: 1fr; }\n  table { display: block; overflow-x: auto; }\n  nav { position: static; max-height: none; border-right: 0; border-bottom: 1px solid var(--line);\n    padding: 0 0 12px; columns: 2; }\n}\n@media print { .theme { display: none; } .wrap { display: block; padding: 0; } body { background: #fff; } nav { position: static; max-height: none; border: 0; columns: 2; padding: 0 0 12px; font-size: 12px; } h2, h3 { break-after: avoid; } table, .box, li { break-inside: avoid; } }\n/*pro*/\nbody { font: 16px/1.65 "Segoe UI", system-ui, -apple-system, Roboto, sans-serif; }\n.cover { display: flex; gap: 22px; align-items: center; max-width: 1148px; margin: 0 auto; padding: 34px 0 22px;\n  border-bottom: 3px solid var(--accent); }\n@media (max-width: 1180px) { .cover { margin: 0 16px; } }\n.cover img { width: 80px; height: 80px; flex: none; }\n.cover .kicker { text-transform: uppercase; letter-spacing: .14em; font-size: 12px; font-weight: 600; color: var(--muted); }\n.cover h1 { font-size: 2.5rem; line-height: 1.1; margin: 4px 0 6px; letter-spacing: -.01em; }\n.cover .sub { margin: 0; }\n.part { margin: 76px 0 0; padding: 0 0 8px; border-bottom: 2px solid var(--accent); background: none; color: var(--accent);\n  font-size: 13px; font-weight: 700; text-transform: uppercase; letter-spacing: .14em; border-radius: 0; }\nh2 { font-size: 1.5rem; font-weight: 650; margin: 46px 0 12px; border-top: 0; padding-top: 0; }\nh2 .n { color: var(--accent); margin-right: .35em; font-variant-numeric: tabular-nums; }\nh3 { font-weight: 650; }\n.box { border-radius: 4px; }\n.box.ok, .box.warn, .box.bad { color: var(--text); font-weight: 400; }   /* seule la bordure est colorée */\nfigure.shot { margin: 18px 0 22px; max-width: 900px; }\nfigure.shot img { display: block; width: 100%; height: auto; border: 1px solid var(--line); border-radius: 6px;\n  box-shadow: 0 2px 12px rgba(0, 0, 0, .14); }\nfigure.shot figcaption { font-size: 13px; color: var(--muted); margin-top: 6px; }\nnav .np { margin: 14px 0 2px; font-size: 12px; font-weight: 700; text-transform: uppercase; letter-spacing: .08em;\n  color: var(--accent); }\n@media print { .cover { margin: 0 0 18px; } .part { break-before: page; margin-top: 0; } figure.shot { break-inside: avoid; } h2 { break-after: avoid; } }\n/*/pro*/\n</style></head><body><main><header><h1>SDR manual</h1><p class="muted">TinySA Monitor — the SDR station (V8)</p></header><nav><h2>Contents</h2><ol><li><a href="#poste">The SDR station</a></li>\n<li><a href="#branchement">First connection</a></li>\n<li><a href="#ecoute">Listening</a></li>\n<li><a href="#favoris">Favourites and patrol</a></li>\n<li><a href="#surveiller">Monitoring with the SDR</a></li>\n<li><a href="#plusieurs">Several SDRs and the map</a></li>\n<li><a href="#caler">Calibrating the levels on the tinySA</a></li>\n<li><a href="#remonter">Going back in time</a></li>\n<li><a href="#demo">The SDR demo</a></li>\n<li><a href="#emettre">Transmitting with a HackRF</a></li>\n<li><a href="#sons">Sounds, generator and alarms</a></li>\n<li><a href="#avance">Advanced tools</a></li>\n<li><a href="#savoir">Good to know</a></li></ol></nav><section id="poste"><h2>1. The SDR station</h2>\n<p>An <b>SDR</b> (software-defined radio: HackRF, SDRplay RSP1B, RTL-SDR, Airspy, WiNRADiO…) receives a <b>window</b> of a\nfew MHz at once, without gaps, and can <b>demodulate</b>: you hear what is on a frequency. The tinySA sweeps a whole\nband but listens to nothing. The two complement each other.</p>\n<h3>Three modes</h3>\n<p>The mode button, in the top bar, chooses what you use:</p>\n<table>\n  <tr><th>Mode</th><th>On screen</th></tr>\n  <tr><td><b>📟 tinySA</b></td><td>The app as before: spectrum, waterfall, wall, list.</td></tr>\n  <tr><td><b>📡 SDR</b></td><td>The SDR station panels: Receiver, Spectrum, Waterfall, My mics.</td></tr>\n  <tr><td><b>📟+📡 Combined</b></td><td>The tinySA spectrum AND the SDR spectrum side by side: the tinySA watches the whole\n    site, the SDR listens and looks closely.</td></tr>\n</table>\n<p>Each mode has a base layout and <b>preset views</b> (listen, monitor, analyse, dual screen). Then move the panels as\nyou like: your layout is remembered, and it follows your user profile.</p>\n<h3>The four panels</h3>\n<ul>\n  <li><b>Receiver</b>: ▶ / ■, sound, the big <b>A</b> frequency (scroll wheel on a digit to change it), the meter in\n    dBm with a word (very weak, weak, good, strong, too strong), ⭐ favourites, patrol, alarms, the “what is it” info\n    and the pilot.</li>\n  <li><b>Spectrum</b>: the SDR window. Your mics are marked by name. <b>Click = listen (A)</b>, <b>right-click = B</b>.\n    Previous / next mic, zoom, peak hold.</li>\n  <li><b>Waterfall</b>: the history of the window, A and B as lines.</li>\n  <li><b>My mics</b>: this SDR\'s mics with their level; double-click = listen, right-click = menu.</li>\n</ul>\n<h3>Simple, Plus, Expert</h3>\n<p>The app\'s display level also applies to the SDR station. <b>Simple</b>: listen, favourites, patrol, alarms.\n<b>Plus</b>: demodulation, step, squelch, receiver B, recordings. <b>Expert</b>: FFT size, device settings, load and\nsaturation.</p>\n</section>\n<section id="branchement"><h2>2. First connection</h2>\n<p>The first time, open <b>🔌 First SDR connection</b> (mode menu, or 🔌 Hardware › 📡 SDR). The wizard does six steps\nand says ✔, ⚠ or ✖ for each, with what to do:</p>\n<ol>\n  <li><b>My SDR</b>: choose the exact model. It sets the rates, gains and frequency range.</li>\n  <li><b>Find it</b>: the SDR tool is looked for, the device detected, a signal received for 2 s and the rate\n    checked. If a line is ✖, it says why (missing tool, USB driver, SDR taken by another program, USB port too\n    slow).</li>\n  <li><b>Set the gain automatically</b>: each input gain value is tried; the app keeps <b>the highest that doesn\'t\n    saturate</b>, with 6 dB of headroom. If it saturates even at the lowest, it advises an attenuator.</li>\n  <li><b>Listen to a mic</b>: the station starts on one of your mics: you should hear it.</li>\n  <li><b>Calibrate the levels</b> (optional): see the chapter “Calibrating the levels on the tinySA”.</li>\n  <li><b>Diagnostics</b>: a file sums everything up (model, gains, results, tool messages). Send it to support if\n    something gets stuck.</li>\n</ol>\n<div class="box">The SDR tools (hackrf_transfer, rtl_sdr, SoapySDR…) come from the <b>SDR kit</b> to unzip next to the\napp, or from PothosSDR. The SDRplay also needs the maker\'s API, the WiNRADiO its software.</div>\n</section>\n<section id="ecoute"><h2>3. Listening</h2>\n<p>An analog wireless mic is listened to like a radio: the station demodulates the FM and plays the sound. Two quick\nways to tune to a mic:</p>\n<ul>\n  <li><b>Double-click</b> its name or frequency in “My frequencies” (in SDR or combined mode);</li>\n  <li><b>click</b> it in the SDR spectrum, or in “My mics”.</li>\n</ul>\n<h3>The listening setting is automatic</h3>\n<p>Each device transmits its own way: wide FM, de-emphasis, <b>compander</b> (compressor at the transmitter, expander at\nthe receiver). The app <b>guesses the right setting</b> from what it knows about the mic: its device in the imported plan\n(EazyRF, WWB, WSM…), its group name, its name. The 🎧 Listening line shows “auto (from the mic)”. If you change the\npreset or the compander, your choice is <b>remembered for this mic</b> (“✋ chosen for this mic”), in the list and in\nshows.</p>\n<div class="box warn"><b>Digital</b> systems (ULX-D, Axient Digital, QLX-D, SLX-D, EW-D / EW-DX, 6000, Spectera…)\n<b>can\'t be listened to</b>: their sound is coded and often encrypted. The app says so (📵) and keeps monitoring their\nlevel. Manufacturers don\'t publish their companders: the app\'s are approximations, tuned to sound pleasant, not exact\ncopies.</div>\n<h3>Receivers A and B</h3>\n<p>At Plus level, a second receiver <b>B</b> listens to another frequency of the same window. “A left / B right” puts\neach in one ear of the headphones.</p>\n<h3>Squelch, volume, recording</h3>\n<p>The <b>squelch</b> cuts the hiss when nothing is on. <b>⏺ Sound</b> records what you hear as WAV, <b>⏺ IQ</b>\nrecords the raw signal of the whole window (large files, to replay in Real time). Both ask for your consent the first\ntime (voices can be recorded).</p>\n</section>\n<section id="favoris"><h2>4. Favourites and patrol</h2>\n<h3>Favourites on the numeric keypad</h3>\n<p>Put your most important mics on keys <b>1 to 9 of the numeric keypad</b>: right-click a ⭐ button of the Receiver\n(“put the listened mic here”) or right-click a mic in “My mics”. Then <b>one key = the SDR tunes to that mic, with its\nlistening setting</b>, wherever you are in the app.</p>\n<h3>🔁 Patrol</h3>\n<p>The patrol moves the SDR from one favourite to the next (or through all this SDR\'s mics), a few seconds each,\nin frequency order (the SDR re-centres as little as possible).\nSwitched-off 💤 or paused mics are skipped. <b>A keypad key, a click on a frequency or a double-click stops the\npatrol</b>: you took over.</p>\n</section>\n<section id="surveiller"><h2>5. Monitoring with the SDR</h2>\n<p>The SDR window <b>also monitors your frequencies</b>: the mics in it get their level, states and alarms, as with the\ntinySA. If a tinySA sweeps at the same time, it keeps the monitoring (the two scales aren\'t mixed).</p>\n<h3>🚨 Tune to alarms</h3>\n<p>When a <b>new</b> alarm comes in (conflict, intermod, absent, too strong, pilot) on a mic of this SDR, the station\n<b>tunes to it by itself</b>: you hear what\'s going on, and the log notes what the SDR sees there (“what is it”). It\ndoesn\'t steal a frequency you just chose (30 s), and it stays at least 20 s on an alarm before moving to the next.\n<b>↩ Go back</b> takes you back to where you were. If the SDR monitors alone and the alarm is outside its window, it\ndoesn\'t move by itself (the other mics would lose their measurement): it offers <b>🚨 Go to the alarm</b>. Tick “and record the sound” to keep a WAV of the alarm (10 s before\nif the SDR was already on that mic, 20 s after).</p>\n<h3>🏷 What is it?</h3>\n<p>Under the frequency, the app says what it sees on A from the shape of the spectrum: analog FM mic, narrow FM\n(walkie-talkie), pure carrier, digital block, TV… with the occupied width and the dB above the noise. It\'s a useful\n<b>guess</b> for sorting, not a certain identification.</p>\n<h3>🔊 The pilot: “it really is your transmitter”</h3>\n<p>Many analog mics transmit an inaudible tone, the <b>pilot</b>. The first time the SDR hears it on a mic, it\nasks <b>“is it really your transmitter?”</b>: ✔ Yes remembers it, ✖ No ignores it (an interferer can have a pilot\ntoo). Then: “✔ it really is your transmitter”. If a carrier is there <b>without</b> its pilot for 5 s, a\n<b>PILOT</b> alarm is raised: maybe another transmitter on your frequency. A pack without a pilot simply shows “no\npilot seen”. Right-click the info line = forget the pilot (if you changed pack).</p>\n</section>\n<section id="plusieurs"><h2>6. Several SDRs and the map</h2>\n<p><b>📡 My SDRs</b> adds stations (up to 4): each has its name, model, serial number (to tell them apart) and <b>its\nscenes</b>. An SDR attached to a scene only handles that scene\'s mics, and it answers the keypad and the alarms of\nthose mics. Each station has its four panels, titled with its name.</p>\n<p>On the <b>🗺 site map</b>, SDRs are tiles like the tinySAs: <b>drag an SDR onto a scene</b> so it monitors it; the\nline between them shows who monitors what.</p>\n</section>\n<section id="caler"><h2>7. Calibrating the levels on the tinySA</h2>\n<p>An SDR measures in <b>dBFS</b> (relative to its converter), not in dBm. Without calibration, its levels are\napproximate. <b>📏 Calibrate the SDR levels on the tinySA</b> makes them comparable:</p>\n<ol>\n  <li>Run the tinySA and the SDR at the same time (combined mode), antennas <b>in the same place</b>.</li>\n  <li>Switch on mics in the SDR window (at least 2 signals seen by both are needed).</li>\n  <li>▶ Measure: for 15 s, the app compares the power of each signal (over ± 100 kHz) seen by both.</li>\n  <li>It shows the correction (and the spread between signals). <b>✔ Apply</b> keeps it for this SDR model.</li>\n</ol>\n<p>Then the SDR\'s thresholds, alarms and levels are in real dBm, consistent with the tinySA. Do it again if you change\nantenna, cable or gain.</p>\n</section>\n<section id="remonter"><h2>8. Going back in time</h2>\n<p>The SDR station keeps the <b>last minutes</b> (1, 3 or 5, or off) in memory: the spectrum and the sound heard.\n<b>⏪ Go back in time</b> (Receiver button) shows the waterfall of those minutes, most recent at the top, with alarms as\nmarkers.</p>\n<ul>\n  <li><b>Click</b> the waterfall = pick a moment; the window says which mic A was on at that time.</li>\n  <li><b>▶ Replay from here</b>: up to 60 s of what you were hearing.</li>\n  <li><b>💾 Keep this passage</b>: the sound (WAV) and the image, in the recordings folder.</li>\n</ul>\n<div class="box">Everything stays <b>in memory</b> and disappears when you close the app, except what you keep. Sound\ntakes about 11 MB per minute and per station.</div>\n</section>\n<section id="demo"><h2>9. The SDR demo</h2>\n<p>No SDR yet? <b>🧪 SDR demo</b> (mode menu) runs the whole station <b>without hardware</b>: the app makes the signals\nof <b>your mics</b>, each with a sound (voice “one, two”, melody, beeps…) and a pilot. To make it lively: an interferer\npasses on your first “must stay free” frequency, a mic switches off now and then, another loses its pilot, and two TV\nchannels are there. You can try everything: listening, favourites, patrol, alarms, going back in time, several\nSDRs.</p>\n<p>Right-click a mic in “My mics” › <b>🎵 Sound of this mic in the SDR demo</b> to give it the sound of your choice (see\n“Sounds, generator and alarms”).</p>\n</section>\n<section id="emettre"><h2>10. Transmitting with a HackRF</h2>\n<div class="box warn"><b>Transmitting over the air without authorisation is forbidden.</b> This feature is for working\n<b>on a cable</b>, with an attenuator of 30 dB or more before the receiver\'s or tinySA\'s input.</div>\n<p>A HackRF can <b>transmit</b> (SDRplay, RTL-SDR, Airspy and WiNRADiO only receive). <b>📡 Transmit with a HackRF</b>\nsends up to 8 signals at once in a window of a few MHz:</p>\n<ul>\n  <li><b>FM mic</b> with sound and pilot (test a receiver, its squelch, the app\'s listening);</li>\n  <li><b>walkie-talkie</b> (narrow FM), <b>pure carrier</b>, <b>wide block</b> (digital, TV);</li>\n  <li><b>intermittent</b>: on 1 s every 4 s, like an interferer that comes and goes (hunting practice, alarm tests);</li>\n  <li>several carriers at once: deliberate <b>intermodulation</b>, to watch on the tinySA.</li>\n</ul>\n<p>The transmit gain starts at 0 dB and the amp is off: on a cable, that\'s plenty. Transmission stops by itself (1 to\n30 min), when the window or the app closes, and it is logged. The “on a cable” box is required. A HackRF receives OR\ntransmits: stop the SDR station using it before transmitting.</p>\n<p>With the <b>SDR demo</b> on, transmission is <b>simulated</b>: nothing goes out, and the SDR demo “receives” what you\ntransmit. Handy to try everything without hardware.</p>\n</section>\n<section id="sons"><h2>11. Sounds, generator and alarms</h2>\n<p>Wherever the app plays or makes a sound, you can choose the <b>source</b>:</p>\n<table>\n  <tr><th>Source</th><th>What it is</th></tr>\n  <tr><td>Generator: one frequency</td><td>A tone from 20 Hz to 20 kHz.</td></tr>\n  <tr><td>Generator: sweep</td><td>From f1 to f2 in N seconds, logarithmic (same time per octave) or linear,\n    looped.</td></tr>\n  <tr><td>White noise, pink noise</td><td>To hear how an audio chain behaves.</td></tr>\n  <tr><td>Voice, melody, beeps, silence</td><td>The demo sounds (silence = carrier only).</td></tr>\n  <tr><td>An app sound</td><td>Critical, normal, info alarms, mic roll call.</td></tr>\n  <tr><td>My WAV file</td><td>Your voice, your music, a test signal: looped.</td></tr>\n</table>\n<p>It can be chosen: for each transmitted signal, for each mic of the SDR demo, in the <b>🎵 Audio generator</b> (which\nplays on the app\'s audio output, continuously) and for the <b>alarm sounds</b>: ⚙ Settings › Sound › Alarm sounds, one\nchoice per sound (▶ to listen, ↺ back to the original sound). A custom alarm sound is cut at 4 s; if it can\'t be\nplayed, the app plays the original sound.</p>\n<div class="box">When listening to a wireless mic, highs above ~15 kHz are cut: that\'s a mic\'s audio band, not a\nfault.</div>\n</section>\n<section id="avance"><h2>12. Advanced tools</h2>\n<ul>\n  <li><b>📡 Multichannel monitor</b>: all the mics of a window measured at once (level, neighbours, width), the most\n    important demodulated (sound, deviation, drift, dropouts), automatic incident folders (IQ before and after,\n    report), show phases (rehearsal / show) compared.</li>\n  <li><b>⏱ Real time</b>: a fixed window seen without gaps, with persistence, short signals logged, IQ recording and\n    replay.</li>\n  <li><b>📦 Replay an incident</b>: the report and IQ of an incident, the mic\'s timeline followed during playback.</li>\n  <li><b>📶 Network receivers</b>: RF levels, batteries and alerts read straight from Shure receivers (ULX-D, QLX-D,\n    Axient Digital…) and Sennheiser (evolution G3 / G4, EW-DX, 6000 via Sound Control), compared with what the tinySA\n    and SDR measure. Wisycom publishes no protocol: no direct reading.</li>\n  <li><b>📱 Listening on the phone</b>: the “Listening” view of the web page (hidden by default) plays the SDR on a\n    phone of the network, with the PIN code.</li>\n</ul>\n</section>\n<section id="savoir"><h2>13. Good to know</h2>\n<ul>\n  <li>An SDR can only be used by <b>one program at a time</b>: close the other program (and the app\'s SDR windows using\n    it) before starting the station.</li>\n  <li>An SDR\'s <b>window</b> is a few MHz wide (HackRF up to ~15 MHz, RSP1B ~8 MHz, RTL-SDR ~2 MHz): when A leaves the\n    window, the station re-centres by itself.</li>\n  <li>A HackRF has 8 bits: a very strong transmitter nearby saturates it quickly. The automatic gain setting and an\n    attenuator fix that.</li>\n  <li>An SDR\'s levels are only in real dBm after <b>calibration</b> on the tinySA (or for a WiNRADiO, factory\n    calibrated).</li>\n  <li>Recorded sound and IQ are kept for the time you choose (📡 SDR settings › recordings kept), then deleted.</li>\n</ul>\n</section></main></body></html>\n'}
